def endpoint(environ):
    port = environ.get("PORT", 8080)
    try:
        port = int(port)
    except (TypeError, ValueError):
        raise ValueError
    if not 1 <= port <= 65535:
        raise ValueError
    host = environ.get("HOST", "127.0.0.1")
    if host == "::1":
        host = "[::1]"
    return f"{host}:{port}/health"

